package gatetable

// peakSlots returns the maximum number of simultaneously held shared slots.
// Every frame instance has interval [release+k*period, release+k*period+L)
// with L in [1,2*period].
func peakSlots(period int, releases, latencies []int) int {
	best := 0
	for t := 0; t < period; t++ {
		count := 0
		for f, release := range releases {
			l := latencies[f]
			// For t in [0,period), an interval covering t can only be
			// generated by these few generations when L <= 2*period.
			for k := -2; k <= 1; k++ {
				start := release + k*period
				if start <= t && t < start+l {
					count++
				}
			}
		}
		if count > best {
			best = count
		}
	}
	return best
}

// tableEntries counts maximal circular runs of equal masks.  A constant
// sequence has one entry.
func tableEntries(masks []uint8) int {
	t := len(masks)
	if t == 0 {
		return 0
	}
	changes := 0
	for i := 0; i < t; i++ {
		if masks[i] != masks[(i+t-1)%t] {
			changes++
		}
	}
	if changes == 0 {
		return 1
	}
	return changes
}

// CountTableEntries counts physical entries for a circular mask sequence.
// Every maximal circular run of equal masks is one entry; a constant
// sequence, including an all-zero one, counts as one entry.
func CountTableEntries(masks []uint8) int {
	return tableEntries(masks)
}

// compressMasks returns the circular physical-table spans.  Ticks belonging
// to span i are (Start+j) mod period for j in [0,Length).  A constant mask
// yields one span of length period.
func compressMasks(masks []uint8) []MaskSpan {
	t := len(masks)
	if t == 0 {
		return nil
	}
	start := -1
	for i := 0; i < t; i++ {
		if masks[i] != masks[(i+t-1)%t] {
			start = i
			break
		}
	}
	if start < 0 {
		return []MaskSpan{{Start: 0, Length: t, Mask: masks[0]}}
	}

	var spans []MaskSpan
	i := 0
	for i < t {
		pos := (start + i) % t
		mask := masks[pos]
		length := 1
		for i+length < t && masks[(start+i+length)%t] == mask {
			length++
		}
		spans = append(spans, MaskSpan{Start: pos, Length: length, Mask: mask})
		i += length
	}
	return spans
}

// CompressMasks exports circular mask compression for driver diagnostics.
func CompressMasks(masks []uint8) []MaskSpan {
	return compressMasks(masks)
}

func countPortEntries(busy bitset, period int) int {
	if period <= 0 {
		return 0
	}
	transitions := 0
	for i := 0; i < period; i++ {
		if busy.test(i) != busy.test((i+period-1)%period) {
			transitions++
		}
	}
	if transitions == 0 {
		return 1
	}
	return transitions
}
